/**
 * BI-01.2 — 自定义斜杠命令引擎: ~/.bi/commands/ 与 .bi/commands/ 下的 *.md 命令文件。
 *
 * frontmatter 声明 name/description/args; 模板体支持类 Shell 参数注入:
 * $ARGUMENTS 全文、$1..$n 位置参数、{{args}} 双花括号形态。
 * 未提供参数的必选占位 → 结构化错误 (不抛异常, 与 compact.ts 同风格)。
 *
 * 安全边界: 本文件只做命令发现与文本展开, 不执行任何 Shell/子进程;
 * 文件系统经 injectFs 注入 (零 node:fs 依赖), 变量展开归 shell-expansion.ts,
 * 命令真实执行归 BI-06 调度表面。零依赖; strict。
 */

// ---------------------------------------------------------------------------
// 类型
// ---------------------------------------------------------------------------

/** 注入文件系统端口: 发现器经此读目录与文件 (禁止直接 import node:fs)。 */
export interface CommandFs {
  /** 列出目录下的条目名 (不含路径; 目录不存在时应 reject 或返回空)。 */
  readdir(path: string): Promise<string[]>;
  /** 读取 UTF-8 文本文件; 文件不可读时 reject。 */
  readFile(path: string): Promise<string>;
}

/** 单条自定义命令的解析产物。 */
export interface SlashCommand {
  /** 斜杠名 (不含前导 /): frontmatter name 优先, 缺省取文件名去 .md。 */
  name: string;
  /** 描述 (TUI 补全用); 缺省空串。 */
  description: string;
  /** args 声明原文 (如 `<query> [limit]`); 缺省空串。 */
  argsSpec: string;
  /** 必选位置参数名 (argsSpec 中 `<...>` 依序)。 */
  requiredArgs: string[];
  /** 可选位置参数名 (argsSpec 中 `[...]` 依序)。 */
  optionalArgs: string[];
  /** 来源文件路径 (发现顺序内的拼接路径)。 */
  sourceFile: string;
  /** frontmatter 之后的模板体 (原样保留, 展开 在 expandCommand 进行)。 */
  body: string;
}

/** 结构化错误 (与 compact.ts 的 CommandError 判别联合同风格)。 */
export type SlashCommandError =
  | { code: 'missing-required'; message: string; missing: string[] }
  | { code: 'invalid-frontmatter'; message: string; file: string };

export type SlashParse = { ok: true; text: string } | { ok: false; error: SlashCommandError };

/** 单文件发现失败告警 (不中断整体发现)。 */
export interface DiscoveryWarning {
  file: string;
  message: string;
}

/** 发现结果: 命令注册表 + 非致命告警。 */
export interface DiscoveryResult {
  commands: SlashCommand[];
  warnings: DiscoveryWarning[];
}

/** TUI 补全列表条目形态 (调度表面的最小表面)。 */
export interface SlashCommandSurfaceEntry {
  name: string;
  description: string;
}

// ---------------------------------------------------------------------------
// frontmatter 解析
// ---------------------------------------------------------------------------

/** 提取文件名末端段 (零 path 依赖, 手工拼接已由调用方保证分隔符)。 */
export function baseName(p: string): string {
  const idx = p.lastIndexOf('/');
  return idx >= 0 ? p.slice(idx + 1) : p;
}

/** 拼接目录与条目名 (容忍目录尾随 /)。 */
export function joinPath(dir: string, entry: string): string {
  if (dir.endsWith('/')) return dir + entry;
  return dir + '/' + entry;
}

/**
 * 解析 frontmatter: 仅识别文件头部 `---` 围栏内的 `key: value` 行。
 * 返回 null 表示无 frontmatter 围栏 (首行非 ---); 围栏未闭合视为畸形。
 */
export function parseFrontmatter(
  source: string,
): { fields: Record<string, string>; body: string; malformed: boolean } {
  const lines = source.split('\n');
  if ((lines[0] ?? '').trim() !== '---') {
    return { fields: {}, body: source, malformed: false };
  }
  const fields: Record<string, string> = {};
  let endIdx = -1;
  for (let i = 1; i < lines.length; i++) {
    if ((lines[i] ?? '').trim() === '---') {
      endIdx = i;
      break;
    }
    const line = lines[i] ?? '';
    const sep = line.indexOf(':');
    if (sep <= 0) continue; // 非法行静默跳过 (注释/空行)
    const key = line.slice(0, sep).trim();
    const value = line.slice(sep + 1).trim();
    if (key !== '') fields[key] = value;
  }
  if (endIdx === -1) {
    // 围栏未闭合: 畸形, 全文当 body 交由上层告警
    return { fields: {}, body: source, malformed: true };
  }
  const body = lines.slice(endIdx + 1).join('\n');
  return { fields, body, malformed: false };
}

/**
 * 解析 args 声明: `<name>` = 必选位置参数, `[name]` = 可选位置参数 (依序)。
 * 其余字符 (空格、字面词) 忽略。返回 [必选名数组, 可选名数组]。
 */
export function parseArgsSpec(spec: string): [string[], string[]] {
  const required: string[] = [];
  const optional: string[] = [];
  const pattern = /<([^<>]+)>|\[([^\[\]]+)\]/g;
  let m: RegExpExecArray | null;
  while ((m = pattern.exec(spec)) !== null) {
    if (m[1] !== undefined) {
      required.push(m[1].trim());
    } else if (m[2] !== undefined) {
      optional.push(m[2].trim());
    }
  }
  return [required, optional];
}

// ---------------------------------------------------------------------------
// 参数注入
// ---------------------------------------------------------------------------

/**
 * 类 Shell 参数注入到模板体:
 * - `$ARGUMENTS` 与 `{{args}}` → argv 全文 (单空格连接);
 * - `$1..$n` → 第 n 个位置参数 (越界 → 空串; `$0` 不展开, 保留字面);
 * - 越界的可选位置 → 空串。
 * 必选占位不足 → missing-required 结构化错误。
 */
export function expandCommand(cmd: SlashCommand, argv: string[]): SlashParse {
  const missing: string[] = [];
  for (let i = 0; i < cmd.requiredArgs.length; i++) {
    const name = cmd.requiredArgs[i] ?? '';
    if (argv[i] === undefined || argv[i] === '') missing.push(name);
  }
  if (missing.length > 0) {
    return {
      ok: false,
      error: {
        code: 'missing-required',
        message: `/${cmd.name} 缺少必选参数: ${missing.join(', ')} (声明: ${cmd.argsSpec})`,
        missing,
      },
    };
  }
  const full = argv.join(' ');
  // 单遍扫描: 展开产物只写入输出、永不被重扫 (参数内容含 $1/$ARGUMENTS/{{args}}
  // 字面时不二次展开 —— 注入安全)。
  const body = cmd.body;
  let out = '';
  let i = 0;
  while (i < body.length) {
    if (body.startsWith('{{args}}', i)) {
      out += full;
      i += '{{args}}'.length;
      continue;
    }
    if (body.startsWith('$ARGUMENTS', i)) {
      out += full;
      i += '$ARGUMENTS'.length;
      continue;
    }
    const ch = body[i] ?? '';
    if (ch === '$') {
      let j = i + 1;
      let digits = '';
      while (j < body.length && (body[j] ?? '') >= '0' && (body[j] ?? '') <= '9') {
        digits += body[j] ?? '';
        j += 1;
      }
      if (digits !== '') {
        const n = Number(digits);
        if (n > 0) {
          out += argv[n - 1] ?? ''; // 越界可选 → 空串; $0 走下方字面
          i = j;
          continue;
        }
      }
    }
    out += ch; // $0、$(、$$ 等非位置形态保留字面
    i += 1;
  }
  return { ok: true, text: out };
}

// ---------------------------------------------------------------------------
// 发现
// ---------------------------------------------------------------------------

/** 单目录展开: 读取 *.md 并解析为 SlashCommand; 缺目录 → 空 (容忍)。 */
async function discoverDir(dir: string, fs: CommandFs): Promise<[SlashCommand[], DiscoveryWarning[]]> {
  const commands: SlashCommand[] = [];
  const warnings: DiscoveryWarning[] = [];
  let entries: string[];
  try {
    entries = await fs.readdir(dir);
  } catch {
    return [commands, warnings]; // 缺目录容错: 静默跳过
  }
  for (const entry of entries) {
    if (!entry.endsWith('.md')) continue;
    const file = joinPath(dir, entry);
    let source: string;
    try {
      source = await fs.readFile(file);
    } catch (err) {
      warnings.push({ file, message: `读取失败: ${String(err)}` });
      continue;
    }
    const fm = parseFrontmatter(source);
    if (fm.malformed) {
      warnings.push({ file, message: 'frontmatter 围栏未闭合 (---)' });
      continue;
    }
    const fallbackName = entry.slice(0, -3);
    const declaredName = fm.fields['name'] ?? '';
    const [requiredArgs, optionalArgs] = parseArgsSpec(fm.fields['args'] ?? '');
    commands.push({
      name: declaredName !== '' ? declaredName : fallbackName,
      description: fm.fields['description'] ?? '',
      argsSpec: fm.fields['args'] ?? '',
      requiredArgs,
      optionalArgs,
      sourceFile: file,
      body: fm.body,
    });
  }
  return [commands, warnings];
}

/**
 * 扫描多目录的 *.md 自定义命令。dirs 依优先序排列: 同名冲突时
 * 下标靠前者优先 (先到先得, 后到者丢弃)。缺目录不报错 (跳过)。
 */
export async function discoverSlashCommands(dirs: string[], injectFs: CommandFs): Promise<DiscoveryResult> {
  const commands: SlashCommand[] = [];
  const warnings: DiscoveryWarning[] = [];
  const seen = new Set<string>();
  for (const dir of dirs) {
    const [dirCommands, dirWarnings] = await discoverDir(dir, injectFs);
    for (const w of dirWarnings) warnings.push(w);
    for (const cmd of dirCommands) {
      if (seen.has(cmd.name)) continue; // 优先序: 先注册者胜
      seen.add(cmd.name);
      commands.push(cmd);
    }
  }
  return { commands, warnings };
}

// ---------------------------------------------------------------------------
// 调度表面
// ---------------------------------------------------------------------------

/**
 * 返回 TUI 补全列表形态的注册表 (name + description)。
 * 纯函数: 保序输出 (即发现优先序), 不排序不去重 (发现器已去重)。
 */
export function slashCommandSurface(commands: readonly SlashCommand[]): SlashCommandSurfaceEntry[] {
  return commands.map((cmd) => ({ name: cmd.name, description: cmd.description }));
}

#!/usr/bin/env bun
/**
 * bi 真入口：BI-20.2 建立、BI-23.1 接 main 分发、BI-24.2 接 REPL 主路径。
 *
 * 装配序（kimi 装配参考 main→cli→tui 段）：
 * - 无参 = 交互 REPL：配置装配（三级 TOML+env）→ BI-02 凭据门 → BI-04.2 真实
 *   驱动 → AgentTuiSession（writer=stdout）→ runRepl（InputLoop→KeyStream 真实桥）；
 *   凭据/配置失败结构化退出码 3（与 headless 同一面）。
 * - 带参 = runBi 全局分发（--version/--help/--prompt 无头/八子命令，BI-24.1）。
 */
import { ConfigService } from "../packages/core/src/config/config-service";
import { ConfigError } from "../packages/core/src/config/schema";
import { resolveModelPort, ModelPortConfigError } from "../packages/core/src/cli/model-port";
import { buildDefaultToolset } from "../packages/core/src/cli/toolset";
import { runBi } from "../packages/core/src/cli/main";
import { AgentTuiSession, MOUSE_DISABLE, MOUSE_ENABLE } from "../packages/tui/src/mount/agent-tui";
import { KeyStream, runRepl } from "../packages/tui/src/mount/repl";
import { InputLoop } from "../packages/tui/src/engine/diff-renderer";
import { PermissionGate } from "../packages/core/src/guard/permission-gate";
import { permissionModeFromConfig, PermissionSessionController } from "../packages/core/src/cli/permission-mode";
import {
  PERMISSIONS_USAGE,
  permissionsCommand,
} from "../packages/core/src/cli/commands/permissions-command";
import { discoverSlashCommands, slashCommandSurface } from "../packages/core/src/commands/custom-commands";
import { homedir } from "node:os";
import { join } from "node:path";
import { readFile, readdir } from "node:fs/promises";

import { builtinSlashCandidates } from "../packages/tui/src/mount/candidate-menu";

type RawCapableStdin = AsyncIterable<Uint8Array> & { isTTY?: boolean; setRawMode?: (on: boolean) => void };

/** BI-27.4 内置候选兜底(tui 命令面最小集;发现失败/空目录时仍可用)。 */
const builtinFallback = builtinSlashCandidates;

/** 交互 REPL 主路径（bin 层装配；REPL v1 纯对话，工具注册表面归后续装配卡）。 */
async function runReplMain(stdin: RawCapableStdin): Promise<number> {
	try {
		const service = new ConfigService();
		const config = await service.load();
		const selection = resolveModelPort(config, {
			resolveApiKey: (name) => service.resolveProviderApiKey(name),
		});
		process.stderr.write(`bi: 模型已装配 provider=${selection.providerName} mode=${selection.mode} model=${selection.wireModel}\n`);

		// BI-28.3 接线:权限面单实例——config [permission] mode/rules 建门禁(规则
		// 缺 scope 补 always),控制器喂 /permissions 命令面;工具回路与命令面共享。
		const gate = new PermissionGate({ mode: permissionModeFromConfig(config.permission?.mode) });
// config 规则的 ask 动作 = 缺省语义,门禁静态层(allow/deny)不表,装配时剔除
		const staticRules: PermissionRule[] = [];
		for (const rule of config.permission?.rules ?? []) {
			if (rule.action === "ask") continue;
			staticRules.push({ tool: rule.tool, pattern: rule.pattern, action: rule.action, scope: "always" });
		}
		gate.addRules(staticRules);
		const controller = new PermissionSessionController({ gate });

		// BI-27.4 接线:自定义斜杠命令入候选菜单(内置 + ~/.bi/commands + <cwd>/.bi/commands);
		// 发现失败退回内置候选,不影响 REPL 启动。
		let menuCandidates: ReadonlyArray<{ name: string; description: string }> = [];
		try {
			const commandFs = {
				readdir: async (path: string): Promise<string[]> => {
					const entries = await readdir(path, { withFileTypes: true });
					return entries.filter((e) => e.isFile()).map((e) => e.name);
				},
				readFile: async (path: string): Promise<string> => readFile(path, "utf8"),
			};
			const discovered = await discoverSlashCommands(
				[join(homedir(), ".bi", "commands"), join(process.cwd(), ".bi", "commands")],
				commandFs,
			);
			menuCandidates = [...slashCommandSurface(discovered.commands), ...builtinFallback];
		} catch {
			menuCandidates = [...builtinFallback];
		}

		// /permissions 执行面接线(BI-28.3):其余 / 开头行走本地未知命令应答,
		// 均不入模型回合(agent-tui submit 拦截)。
		const slashCommand = async (line: string): Promise<string> => {
			const head = line.trim().split(/\s+/)[0] ?? "";
			if (head === "/permissions") {
				// parse 吃的是去前缀参数体("/permissions" 本身不入参)
				const body = line.trim().replace(/^\/permissions\b/, "").trim();
				const parsed = permissionsCommand.parse(body);
				if (!parsed.ok) return `${parsed.error.message}\n用法: ${PERMISSIONS_USAGE}`;
				return permissionsCommand.execute(parsed.args, controller.toPorts()).join("\n");
			}
			const known = menuCandidates.some((c) => `/${c.name}` === head);
			return known
				? `斜杠命令 ${head} 的执行面尚未接线(候选菜单可用,执行归后续卡)。`
				: `未知斜杠命令: ${head}(可用: /permissions)`;
		};

		const session = new AgentTuiSession({
			model: selection.port,
			tools: buildDefaultToolset(process.cwd()),
			cwd: process.cwd(),
			gate,
			candidates: () => menuCandidates,
			slashCommand,
			// 真实终端尺寸（BI-24.3）：此前缺省 24×80，大终端上提示符钉在第 24 行、
			// 转录画在第 1 行，画面与视口脱节。
			rows: process.stdout.rows ?? 24,
			cols: process.stdout.columns ?? 80,
			writer: { write: (data) => process.stdout.write(data) },
		});
		const keys = new KeyStream();
		// 终端尺寸变更跟随（SIGWINCH；非 TTY 无事件，保守注册）。
		process.on("SIGWINCH", () => {
			session.resize(process.stdout.rows ?? 24, process.stdout.columns ?? 80);
		});

		// 真实输入桥：stdin 字节 → InputLoop（粘贴聚合+按键解析）→ KeyStream。
		// EOF 桥：reader 耗尽（管道关闭/EOF）即 KeyStream.end()——InputLoop 静默
		// 吞掉 reader 结束，REPL 的 eof 终场需此显式信号。
		async function* stdinChunks(): AsyncIterable<Uint8Array> {
			try {
				for await (const chunk of stdin) yield chunk;
			} finally {
				keys.end();
			}
		}
		const loop = new InputLoop(stdinChunks(), (key) => keys.push(key));
		if (stdin.isTTY === true) {
			try {
				stdin.setRawMode?.(true); // raw-mode 尽力而为；失败退化为行式输入
				process.stdout.write(MOUSE_ENABLE); // BI-27.5 滚轮历史:SGR 鼠标上报
			} catch {
				// 忽略：非交互/受限终端
			}
		}
		loop.start();
		try {
			const result = await runRepl({ session, keys, title: "bi repl" });
			return result.endedAs === "session-exited" ? 4 : 0;
		} finally {
			loop.stop();
			if (stdin.isTTY === true) {
				try {
					process.stdout.write(MOUSE_DISABLE); // 离场还原鼠标语义
					stdin.setRawMode?.(false);
				} catch {
					// 忽略
				}
			}
		}
	} catch (cause) {
		if (cause instanceof ConfigError || cause instanceof ModelPortConfigError) {
			process.stderr.write(`bi: ${cause.message}\n`);
			return 3;
		}
		throw cause;
	}
}

const argv = process.argv.slice(2);
process.exitCode =
	argv.length === 0
		? await runReplMain(process.stdin as RawCapableStdin)
		: await runBi(argv, { headless: { tools: buildDefaultToolset(process.cwd()) } });

/**
 * BI-23.2 —— TUI 挂载与事件流：把 BI-23.1 的对话驱动器挂上 BI-19/20 渲染器官。
 * BI-27.2 —— 流式渲染：content_delta 追加 #streamText 缓冲并按 80ms 节流
 *   出帧（时钟走注入 clock.now，缺省 Date.now）；StreamView 组件在状态行
 *   上方（rows-3）单行预览缓冲尾部（前缀 ▌、≤160 码元、超宽截断加 …），缓冲
 *   空不渲染；流收束（正常/取消/异常）清空缓冲并让 StreamView 退场，完整
 *   文本按既有逻辑 transcribe 进投影（落盘行为不变）。running 状态行追加
 *   已用秒数（turnStartedAt 起算，随每帧自然刷新）。
 * BI-27.3 —— 富文本转录：assistant 条目正文走 renderMarkdown（手写零依赖，
 *   标题/粗斜体/行内代码/围栏代码块/列表；latex/mermaid 围栏复用 BI-19.8 /
 *   BI-19.6 现成器官），视图层由 StyledTranscript 承载（与 TranscriptProjection
 *   并行消费同一份 L1 条目；plain 条目文本与 L3 逐字节一致，仅样式新增）。
 *   全部落格走 VirtualTerminal.write 的 Cell 样式面，无裸转义序列。
 * BI-27.4 —— 候选与命令菜单：mount/candidate-menu.ts 提供候选面端口
 *   （CandidatesProvider，缺省 builtinSlashCandidates，与 core
 *   SlashCommandSurfaceEntry 字段同构便于宿主接线）+ CandidateMenu 状态机；
 *   斜杠草稿自动开菜单（前缀/模糊过滤、↑↓ 移动、Tab/Enter 接受、Esc 关闭），
 *   菜单视图画状态行上方（永不触碰状态行/提示行）；非斜杠 Tab 经 provider
 *   前缀延伸补全（mount/repl.ts 路由）。命令真实分发归宿主装配（缝已留）。
 *
 * ─────────────────────────────────────────────────────────────────────────
 * ADR（BI-27.5）：REPL 视口方案裁定 —— 维持 inline（正常屏幕）
 * - 裁定：REPL 继续以「正常屏幕 + 行内重绘窗」为视口架构。不启用 alt-screen
 *   （备用屏全屏 TUI），不引入 scroll region（滚动区域）混合方案。
 * - 理由：kimi Code CLI 基线（RULE-BI-07）为 inline 式 REPL，bi 遵循 shell
 *   基线——stdout 可直接被管道/重定向/日志采集消费；终端原生选择复制、
 *   搜索与滚动习惯零成本保留；进程崩溃不留备用屏残骸。
 * - 语义：转录窗（rows-2 尾窗）是 inline 视口上的差分重绘窗，不是终端
 *   scrollback 本身；窗内历史滚回由本卡滚轮偏移（scrollTranscript，SGR
 *   1000/1006 鼠标上报）承担，不依赖终端原生 scrollback。
 * - 代价（接受）：alt-screen 式全屏布局/原地进度条不在本架构内；重绘窗与
 *   终端原生 scrollback 内容在真实终端上并存（不视为缺陷，不加消除逻辑）。
 * - 复核条件：若未来需要全屏面板（多窗格/内嵌滚动列表编辑器），另立 ADR
 *   评审，不在本卡内渐进混入。
 * ─────────────────────────────────────────────────────────────────────────
 *
 * 挂载面（kimi 装配序 tui 段；器官全量复用、不改动）：
 * - **双缓冲投影**：TranscriptProjection（BI-19.1 同构 L1→L3）承载会话视图，
 *   TuiApp/DiffRenderer（begin/end 差分帧）负责双缓冲提交；onFrame 钩子回吐
 *   每帧可见行集（注入渲染面断言点）。BI-27.3 起渲染面为 StyledTranscript
 *   （富文本），投影保留 L4 导出与同构不变式职责；resize 双侧同步重算
 *   （BI-27.5 折行宽跟随，滚动锚底语义不变）。
 * - **审批 ask 回路**：manual 模式下 PermissionGate 'ask' 决策 → 栈顶审批浮层
 *   （y=允许 / n=拒绝 / Esc=拒绝），回答经 Promise 回喂装配执行体；deny 以
 *   结构化 permission-denied 回喂模型（与无头降级同一回喂语义，不再假冒）。
 * - **Esc 二段取消**：turn 进行中第一段 Esc → AgentLoop.cancelRequest() 等
 *   在飞工具落定转 paused（thinking→paused，BI-07 迁移表），驱动器同步 abort
 *   模型流并优雅收束本回合；cancelWindowMs 窗口内第二段 → exit 终态。paused
 *   会话的下次 submit() 经 resume()（paused→thinking）续转。idle 态 Esc 不消费。
 * - 输入面：本卡以 submit() 挂事件流；行编辑器 REPL 接线（editor 器官挂载）
 *   归后续装配卡。钩子 runner 暂为无头路径专属（挂载卡交付面=投影/审批/取消）。
 */

